CREATE TYPE public.app_role AS ENUM ('admin');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id, role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = _user_id AND role = _role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid, public.app_role) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.has_role(uuid, public.app_role) TO authenticated, service_role;
CREATE POLICY "Read own roles" ON public.user_roles FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE FUNCTION public.restrict_admin_signup() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF lower(NEW.email) IS DISTINCT FROM 'durbilisimguvenlik@gmail.com' OR NEW.is_anonymous IS TRUE THEN RAISE EXCEPTION 'Registration is restricted'; END IF; RETURN NEW; END $$;
CREATE TRIGGER restrict_admin_signup BEFORE INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.restrict_admin_signup();
CREATE FUNCTION public.assign_verified_admin() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF lower(NEW.email) = 'durbilisimguvenlik@gmail.com' AND NEW.email_confirmed_at IS NOT NULL AND NEW.is_anonymous IS NOT TRUE THEN INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'admin') ON CONFLICT DO NOTHING; END IF; RETURN NEW; END $$;
CREATE TRIGGER assign_verified_admin AFTER INSERT OR UPDATE OF email_confirmed_at ON auth.users FOR EACH ROW EXECUTE FUNCTION public.assign_verified_admin();
REVOKE ALL ON FUNCTION public.restrict_admin_signup(), public.assign_verified_admin() FROM PUBLIC, anon, authenticated;
ALTER TABLE public.service_jobs ADD COLUMN ready_at date, ADD COLUMN last_customer_notified_at date, ADD COLUMN collected_at date;
CREATE FUNCTION public.validate_delivery_dates() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN IF NEW.collected_at IS NOT NULL AND NEW.ready_at IS NULL THEN RAISE EXCEPTION 'Ready date required before collection'; END IF; IF NEW.collected_at < NEW.ready_at THEN RAISE EXCEPTION 'Collection cannot precede ready date'; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_delivery_dates BEFORE INSERT OR UPDATE ON public.service_jobs FOR EACH ROW EXECUTE FUNCTION public.validate_delivery_dates();
DO $$ DECLARE t text; p record; BEGIN FOREACH t IN ARRAY ARRAY['camera_jobs','computer_sales','expenses','material_movements','materials','product_sales','products','reminders','security_products','service_jobs','shopping_list'] LOOP FOR p IN SELECT policyname FROM pg_policies WHERE schemaname='public' AND tablename=t LOOP EXECUTE format('DROP POLICY %I ON public.%I',p.policyname,t); END LOOP; EXECUTE format('REVOKE ALL ON public.%I FROM anon, authenticated',t); EXECUTE format('GRANT SELECT, INSERT, UPDATE, DELETE ON public.%I TO authenticated',t); EXECUTE format('GRANT ALL ON public.%I TO service_role',t); EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('CREATE POLICY "Administrator access" ON public.%I FOR ALL TO authenticated USING (public.has_role(auth.uid(), ''admin'')) WITH CHECK (public.has_role(auth.uid(), ''admin''))',t); END LOOP; END $$;
GRANT SELECT ON public.products TO anon;
CREATE POLICY "Public active catalog" ON public.products FOR SELECT TO anon, authenticated USING (is_active = true);
DROP POLICY "Allow delete product images" ON storage.objects;
DROP POLICY "Allow upload product images" ON storage.objects;
CREATE POLICY "Admin upload product images" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id='product-images' AND public.has_role(auth.uid(),'admin'));
CREATE POLICY "Admin update product images" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id='product-images' AND public.has_role(auth.uid(),'admin')) WITH CHECK (bucket_id='product-images' AND public.has_role(auth.uid(),'admin'));
CREATE POLICY "Admin delete product images" ON storage.objects FOR DELETE TO authenticated USING (bucket_id='product-images' AND public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.lookup_tracking(_code text, _kind text DEFAULT 'any') RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$ DECLARE j public.service_jobs; c public.camera_jobs; result jsonb; q integer; BEGIN IF _code IS NULL OR upper(trim(_code)) !~ '^DB-[A-Z0-9]{6}$' OR _kind NOT IN ('any','service','camera') THEN RETURN NULL; END IF; IF _kind IN ('any','service') THEN SELECT * INTO j FROM public.service_jobs WHERE upper(tracking_code)=upper(trim(_code)) LIMIT 1; IF FOUND THEN SELECT count(*) INTO q FROM public.service_jobs WHERE status IN ('pending','in_progress','postponed') AND created_at < j.created_at; RETURN jsonb_build_object('kind','service','queue_position',q,'job',jsonb_build_object('id',j.id,'tracking_code',j.tracking_code,'customer_name',left(j.customer_name,1)||'…','customer_surname',left(j.customer_surname,1)||'…','service_type',j.service_type,'device_name',j.device_name,'status',j.status,'steps',j.steps,'completion_notes',j.completion_notes,'created_at',j.created_at,'ready_at',j.ready_at,'collected_at',j.collected_at)); END IF; END IF; IF _kind IN ('any','camera') THEN SELECT * INTO c FROM public.camera_jobs WHERE upper(tracking_code)=upper(trim(_code)) LIMIT 1; IF FOUND THEN SELECT count(*) INTO q FROM public.camera_jobs WHERE status IN ('bekliyor','devam_ediyor','ertelendi') AND created_at < c.created_at; RETURN jsonb_build_object('kind','camera','queue_position',q,'job',jsonb_build_object('id',c.id,'tracking_code',c.tracking_code,'customer_name',left(c.customer_name,1)||'…','customer_surname','','service_type','device','device_name',c.dvr_model,'status',CASE c.status WHEN 'tamamlandi' THEN 'completed' WHEN 'devam_ediyor' THEN 'in_progress' WHEN 'ertelendi' THEN 'postponed' ELSE 'pending' END,'steps',c.steps,'created_at',c.created_at)); END IF; END IF; RETURN NULL; END $$;
REVOKE ALL ON FUNCTION public.lookup_tracking(text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.lookup_tracking(text,text) TO anon, authenticated, service_role;